public class AnimacionPostproduccion extends Animacion {

    // Atributo nuevo extra
    protected float valorRecursos;


    // Constructor vacío

    public AnimacionPostproduccion() {
		//Traer atributos con el super
        super();
        valorRecursos = 0;
    }


    // Constructor default

    public AnimacionPostproduccion(String codigo, String estudio, String nombre, float horasEstimadas, boolean diurno, int fotogramas, float valorRecursos) {
		//Super para traer todos estos datos
        super(codigo, estudio, nombre, horasEstimadas, diurno, fotogramas);
        this.valorRecursos = valorRecursos;
    }


    // Setter y getter de mi nuevo atributo

    public void setValorRecursos(float newValorRecursos) {
        valorRecursos = newValorRecursos;
    }

    public float getValorRecursos() {
        return valorRecursos;
    }


    // Override del costo. 

    @Override
    public float calcularCosto() {
		//Costo animación NORMAL
        float costoAnimacion = super.calcularCosto();
        // Cálulo del 5% de los recursos Licenciados
        float recargoRecursos = valorRecursos * 0.05f;
        // Agrega el costo fijo de composicion 
		//Regresa solo este
        return costoAnimacion + 80.0f + recargoRecursos;
    }


    // TOverride de entrega

    @Override
    public int tiempoEntrega() {

        return super.tiempoEntrega() + 12;
    }


    // Establece solo 2 intentos.
    @Override
    public int maxIntentos() {

        return 2;
    }


    // Nueva categoría.

    @Override
    public String getCategoria() {

        return "Animacion Postproduccion";
    }
}
